@retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
def init_database():
    global DB_AVAILABLE
    try:
        conn = pymysql.connect(**dict(DB_CONFIG))
        cursor = conn.cursor(DictCursor)
        cursor.execute('\n            CREATE TABLE IF NOT EXISTS chat_sessions (\n                session_id VARCHAR(255) PRIMARY KEY,\n                messages_json LONGTEXT,\n                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP\n            )\n        ')
        cursor.execute('\n            CREATE TABLE IF NOT EXISTS research_tasks_db (\n                task_id VARCHAR(255) PRIMARY KEY,\n                goal TEXT,\n                status TEXT,\n                progress INT,\n                sub_agents_json LONGTEXT,\n                sources_json LONGTEXT,\n                similar_sources_json LONGTEXT,\n                deep_content_json LONGTEXT,\n                report LONGTEXT,\n                metadata_json TEXT,\n                search_params_json TEXT,\n                auto_initiated BOOLEAN DEFAULT FALSE,\n                reason TEXT,\n                session_id VARCHAR(255),\n                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP\n            )\n        ')
        cursor.execute('\n            CREATE TABLE IF NOT EXISTS uploaded_files (\n                id INT AUTO_INCREMENT PRIMARY KEY,\n                unique_filename VARCHAR(500),\n                original_filename VARCHAR(500),\n                size BIGINT,\n                file_type VARCHAR(50),\n                analysis LONGTEXT,\n                content LONGTEXT,\n                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n            )\n        ')
        conn.commit()
        cursor.close()
        conn.close()
        DB_AVAILABLE = True
        logger.success('TiDB Cloud database connected and tables initialized successfully!')
    except Exception as e:
        logger.error(f'Exception caught: {e}')
        DB_AVAILABLE = False
        logger.warning(f'TiDB database not available, using in-memory storage: {str(e)}')
        logger.info('App will work normally with in-memory storage. To use TiDB, provide accessible endpoint.')
init_database()

@retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
@cache.memoize(expire=300)
def get_chat_session(session_id):
    chat_sessions_memory[session_id].last_activity = time.time()
    if not DB_AVAILABLE:
        return dict(chat_sessions_memory[session_id])
    try:
        conn = get_db_connection()
        if not conn:
            return dict(chat_sessions_memory[session_id])
        cursor = conn.cursor(DictCursor)
        cursor.execute('SELECT messages_json FROM chat_sessions WHERE session_id = %s', (session_id,))
        result = cursor.fetchone()
        cursor.close()
        conn.close()
        if result:
            try:
                messages = orjson.loads(result['messages_json'])
                return {'messages': messages, 'last_activity': time.time()}
            except (ValueError, TypeError) as json_error:
                logger.error(f'JSON parsing error in get_chat_session: {str(json_error)}')
                return {'messages': [], 'last_activity': time.time()}
        return {'messages': [], 'last_activity': time.time()}
    except Exception as e:
        logger.error(f'Exception caught: {e}')
        logger.error(f'Error getting chat session: {str(e)}')
        return dict(chat_sessions_memory[session_id])

@retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
def save_chat_session(session_id, messages):
    chat_sessions_memory[session_id].messages = messages
    chat_sessions_memory[session_id].last_activity = time.time()
    cache_key = f"get_chat_session('{session_id}',)"
    cache.delete(cache_key)
    if not DB_AVAILABLE:
        return
    try:
        conn = get_db_connection()
        if not conn:
            return
        cursor = conn.cursor(DictCursor)
        messages_json = orjson.dumps(messages).decode('utf-8')
        cursor.execute('\n            INSERT INTO chat_sessions (session_id, messages_json)\n            VALUES (%s, %s)\n            ON DUPLICATE KEY UPDATE messages_json = %s, updated_at = CURRENT_TIMESTAMP\n        ', (session_id, messages_json, messages_json))
        conn.commit()
        cursor.close()
        conn.close()
        logger.debug(f'Chat session saved: {session_id}')
    except Exception as e:
        logger.error(f'Exception caught: {e}')
        logger.error(f'Error saving chat session to database: {str(e)}')
        raise

