@app.route('/api/chat', methods=['POST'])
def chat():
    try:
        data = request.json
        messages = data.get('messages', [])
        temperature = data.get('temperature', 0.07)
        session_id = data.get('session_id', 'default')
        if not session_id or not session_id.strip():
            session_id = 'default'
        original_user_query = messages[-1]['content'] if messages else ''
        cleaned_query = ftfy.fix_text(original_user_query)
        logger.debug(f"Text fixed with ftfy: '{original_user_query[:50]}...' -> '{cleaned_query[:50]}...'")
        found_keywords = keyword_processor.extract_keywords(cleaned_query.lower())
        logger.info(f'FlashText found keywords: {found_keywords}')
        process_text = curry(lambda x: x.strip())
        normalized_query = toolz_pipe(cleaned_query, str.lower, process_text)
        memory_context = ''
        if supermemory_client:
            try:
                memory_results = supermemory_client.search.execute(q=cleaned_query, limit=5)
                if hasattr(memory_results, 'results') and memory_results.results:
                    memory_context = '\n\n=== KORÁBBI BESZÉLGETÉSEKBŐL EMLÉKEZEM ===\n\n'
                    for i, mem in enumerate(memory_results.results[:3], 1):
                        if hasattr(mem, 'content') and mem.content:
                            clean_mem_content = ftfy.fix_text(mem.content)
                            memory_context += f'{i}. {clean_mem_content}\n'
                    memory_context += '\n=== HASZNÁLD EZT A KONTEXTUST A VÁLASZADÁSHOZ ===\n\n'
            except Exception as mem_error:
                logger.error(f'Exception caught: {mem_error}')
                logger.warning(f'Memory search error (non-critical): {str(mem_error)}')
        needs_search = len(found_keywords) > 0 and len(cleaned_query) > 20
        if not needs_search and len(cleaned_query) > 20:
            fuzzy_matches = fuzzy_process.extract(normalized_query, ['aktuális információ', 'friss hír', 'legújabb adat', 'mai trend'], scorer=fuzz.token_sort_ratio, limit=3)
            if any((score > 70 for _, score in fuzzy_matches)):
                needs_search = True
                logger.info(f'Fuzzy matching triggered search: {fuzzy_matches}')
        if needs_search:
            try:
                search_result = exa_client.search_and_contents(cleaned_query, type='auto', num_results=100, text={'max_characters': 10000}, highlights={'num_sentences': 5})
                search_context = '\n\n=== AKTUÁLIS INFORMÁCIÓK AZ INTERNETRŐL ===\n\n'
                for i, result in enumerate(search_result.results[:5], 1):
                    clean_title = ftfy.fix_text(result.title)
                    search_context += f'Forrás {i}: {clean_title}\n'
                    search_context += f'URL: {result.url}\n'
                    if hasattr(result, 'summary') and result.summary:
                        clean_summary = ftfy.fix_text(result.summary)
                        search_context += f'Összefoglaló: {clean_summary}\n'
                    if hasattr(result, 'text') and result.text:
                        clean_text = ftfy.fix_text(result.text[:50000])
                        search_context += f'Tartalom: {clean_text}...\n'
                    search_context += '\n'
                search_context += '=== VÁLASZOLJ A FENTI AKTUÁLIS INFORMÁCIÓK ALAPJÁN ===\n\n'
                messages_with_context = messages.copy()
                messages_with_context[-1]['content'] = memory_context + search_context + cleaned_query
                messages = messages_with_context
            except Exception as search_error:
                logger.error(f'Exception caught: {search_error}')
                logger.warning(f'Exa search error (non-critical): {str(search_error)}')
        elif memory_context:
            messages_with_context = messages.copy()
            messages_with_context[-1]['content'] = memory_context + cleaned_query
            messages = messages_with_context

        def generate_stream():
            full_content = ''
            try:
                logger.info(f'Starting Cerebras stream with {len(messages)} messages')
                stream = cerebras_client.chat.completions.create(model='gpt-oss-120b', messages=messages, temperature=temperature, max_completion_tokens=65000, top_p=0.05, stream=True)
                logger.info('Stream object created, starting iteration')
                chunk_count = 0
                for chunk in stream:
                    chunk_count += 1
                    if chunk.choices and len(chunk.choices) > 0:
                        delta = chunk.choices[0].delta
                        if hasattr(delta, 'content') and delta.content:
                            content_chunk = delta.content
                            full_content += content_chunk
                            logger.debug(f'Chunk {chunk_count}: {len(content_chunk)} chars')
                            yield f"data: {orjson.dumps({'content': content_chunk, 'done': False}).decode('utf-8')}\n\n"
                logger.info(f'Stream complete, total {chunk_count} chunks, {len(full_content)} chars')
                yield f"data: {orjson.dumps({'content': '', 'done': True}).decode('utf-8')}\n\n"

                def background_save():
                    try:
                        conversationHistory = get_chat_session(session_id)
                        conversationHistory['messages'].append({'role': 'assistant', 'content': full_content})
                        save_chat_session(session_id, conversationHistory['messages'])
                    except Exception as db_error:
                        logger.error(f'Exception caught: {db_error}')
                        logger.error(f'Background DB save failed: {str(db_error)}')
                        traceback.print_exc()
                save_thread = threading.Thread(target=background_save, daemon=False)
                save_thread.start()
                if supermemory_client:
                    try:
                        memory_check_prompt = f'Elemezd a felhasználó üzenetét és döntsd el, tartalmaz-e személyes információt, preferenciát vagy fontos tényt amit érdemes megjegyezni.\n\nFelhasználó üzenete: {cleaned_query}\n\nSzemélyes információk lehetnek:\n- Preferenciák (kedvenc dolgok, amit szeret/nem szeret)\n- Személyes adatok (név, életkor, helyszín, foglalkozás)\n- Célok, tervek, érdeklődési körök\n- Fontos életesemények\n- Szokások, rutinok\n\nVálaszolj CSAK JSON formátumban:\n{{"should_remember": true/false, "memory_content": "mit jegyezzünk meg röviden (1-2 mondat) vagy üres string"}}'
                        mem_decision = cerebras_client.chat.completions.create(model='gpt-oss-120b', messages=[{'role': 'user', 'content': memory_check_prompt}], temperature=0.01, max_completion_tokens=65000, top_p=0.05)
                        if mem_decision.choices:
                            decision_text = mem_decision.choices[0].message.content
                            json_match = re.search('\\{.*\\}', decision_text, re.DOTALL)
                            if json_match:
                                try:
                                    mem_data = orjson.loads(json_match.group())
                                    if mem_data.get('should_remember') and mem_data.get('memory_content'):
                                        supermemory_client.memory.add(content=mem_data['memory_content'])
                                        logger.info(f"Memory saved: {mem_data['memory_content'][:50]}...")
                                except (ValueError, TypeError) as json_error:
                                    logger.warning(f'JSON parsing error in memory decision: {str(json_error)}')
                    except Exception as mem_save_error:
                        logger.error(f'Exception caught: {mem_save_error}')
                        logger.warning(f'Memory save error (non-critical): {str(mem_save_error)}')
                research_decision_prompt = f"""A felhasználóval folytatott beszélgetés alapján döntsd el, hogy érdemes-e automatikus háttérkutatást indítani a témáról.\n\nBeszélgetés utolsó üzenete: {(messages[-1]['content'] if messages else '')}\nVálaszod: {full_content}\n\nElemezd a beszélgetést és döntsd el:\n1. Van-e olyan komplex téma, amiről mélyebb információgyűjtés hasznos lenne?\n2. Kért-e a felhasználó részletes információt, amit kutatással jobban megválaszolhatsz?\n3. Van-e olyan felmerült téma, ahol aktuális, friss információk kellenek?\n\nVálaszolj CSAK az alábbi JSON formátumban, semmi más szöveget:\n{{"should_research": true/false, "research_goal": "kutatási cél leírása vagy üres string"}}"""
                try:
                    decision_response = cerebras_client.chat.completions.create(model='gpt-oss-120b', messages=[{'role': 'user', 'content': research_decision_prompt}], temperature=0.01, max_completion_tokens=65000, top_p=0.05)
                    if decision_response.choices:
                        decision_text = decision_response.choices[0].message.content
                        json_match = re.search('\\{.*\\}', decision_text, re.DOTALL)
                        if json_match:
                            try:
                                decision_data = orjson.loads(json_match.group())
                                if decision_data.get('should_research') and decision_data.get('research_goal'):
                                    task_id = f'task_{int(time.time())}_{os.urandom(4).hex()}'
                                    task_data = AddictDict({'id': task_id, 'goal': decision_data['research_goal'], 'status': 'Automatikus kutatás inicializálása...', 'progress': 0, 'auto_initiated': True, 'reason': decision_data.get('reason', ''), 'session_id': session_id, 'sub_agents': [AddictDict({'name': 'Fő Keresés', 'status': 'Inicializálás...', 'progress': 0}), AddictDict({'name': 'Tartalom Gyűjtő', 'status': 'Várakozás...', 'progress': 0}), AddictDict({'name': 'Hasonló Források', 'status': 'Várakozás...', 'progress': 0}), AddictDict({'name': 'Mély Elemzés', 'status': 'Várakozás...', 'progress': 0}), AddictDict({'name': 'Jelentés Generáló', 'status': 'Várakozás...', 'progress': 0})], 'sources': [], 'similar_sources': [], 'deep_content': [], 'report': '', 'metadata': AddictDict({'total_sources': 0, 'analysis_depth': 0, 'report_length': 0}), 'search_params': AddictDict({'goal': decision_data['research_goal'], 'search_type': 'auto', 'num_results': 100})})
                                    with research_lock:
                                        research_tasks[task_id] = dict(task_data)
                                    save_research_task(task_id, dict(task_data))
                                    thread = threading.Thread(target=execute_comprehensive_research, args=(task_id,))
                                    thread.daemon = False
                                    thread.start()
                                    logger.info(f"Auto-research initiated: {task_id} - {decision_data['research_goal']}")
                            except (ValueError, TypeError) as json_error:
                                logger.warning(f'JSON parsing error in research decision: {str(json_error)}')
                except Exception as e:
                    logger.error(f'Exception caught: {e}')
                    logger.warning(f'Research decision error (non-critical): {str(e)}')
            except Exception as e:
                logger.error(f'Exception caught: {e}')
                logger.error(f'Streaming error: {str(e)}')
                yield f"data: {orjson.dumps({'error': str(e), 'done': True}).decode('utf-8')}\n\n"
        return Response(stream_with_context(generate_stream()), mimetype='text/event-stream')
    except Exception as e:
        logger.error(f'Exception caught: {e}')
        logger.error(f'Chat error: {str(e)}')
        return (jsonify({'error': str(e)}), 500)

@app.route('/api/chat/history/<session_id>', methods=['GET'])
