    return jsonify({'success': True})

@app.route('/api/upload', methods=['POST'])
def upload_file():
    try:
        cleanup_old_uploaded_files()
        if 'file' not in request.files:
            return (jsonify({'error': 'Nincs fájl csatolva'}), 400)
        file = request.files['file']
        if file.filename == '':
            return (jsonify({'error': 'Nincs kiválasztott fájl'}), 400)
        if request.content_length and request.content_length > app.config['MAX_CONTENT_LENGTH']:
            return (jsonify({'error': f"Fájl túl nagy. Maximum: {app.config['MAX_CONTENT_LENGTH'] // (1024 * 1024)} MB"}), 413)
        if not allowed_file(file.filename):
            return (jsonify({'error': f"Nem támogatott fájltípus. Engedélyezett: {', '.join(ALLOWED_EXTENSIONS)}"}), 400)
        filename = secure_filename(file.filename)
        parts = filename.rsplit('.', 1)
        file_ext = parts[1].lower() if len(parts) > 1 else ''
        timestamp = pendulum.now().format('YYYYMMDD_HHmmss')
        unique_filename = f'{timestamp}_{filename}'
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], unique_filename)
        file.save(filepath)
        file_size = os.path.getsize(filepath)
        size_bytes = file_size * ureg.byte
        size_kb = size_bytes.to(ureg.kilobyte)
        size_mb = size_bytes.to(ureg.megabyte)
        file_size_display = f'{sigfig.round(size_mb.magnitude, sigfigs=3)} MB' if size_mb.magnitude > 1 else f'{sigfig.round(size_kb.magnitude, sigfigs=3)} KB'
        logger.info(f'File uploaded: {unique_filename}, size: {file_size_display}')
        content = ''
        quickda_analysis = None
        if file_ext in {'txt', 'md', 'py', 'js', 'html', 'css', 'json', 'xml', 'csv'}:
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    full_content = f.read(500000)
                    if len(full_content) >= 500000:
                        content = full_content
                        logger.warning(f'File {filename} was truncated at 500KB')
                    else:
                        content = full_content
                content = ftfy.fix_text(content)
                content = clean(content, fix_unicode=True, to_ascii=False, lower=False, no_line_breaks=False, no_urls=False, no_emails=False, no_phone_numbers=False, no_numbers=False, no_digits=False, no_currency_symbols=False, no_punct=False, replace_with_punct='', replace_with_url='', replace_with_email='', replace_with_phone_number='', replace_with_number='', replace_with_digit='', replace_with_currency_symbol='')
                logger.info(f'Text content cleaned with cleantext: {len(content)} chars')
                if file_ext == 'csv':
                    try:
                        import pandas as pd
                        df = pd.read_csv(filepath)
                        quickda_report = quickda.quick_eda(df)
                        quickda_analysis = f'\n\n=== QUICKDA CSV ANALYSIS ===\n{quickda_report}\n'
                        logger.success(f'QuickDA analysis completed for CSV: {filename}')
                    except Exception as qda_error:
                        logger.error(f'Exception caught: {qda_error}')
                        logger.warning(f'QuickDA analysis failed: {str(qda_error)}')
            except UnicodeDecodeError:
                content = '[Fájl tartalma nem olvasható UTF-8 kódolással]'
            except Exception as read_error:
                logger.error(f'Exception caught: {read_error}')
                logger.error(f'Error reading file: {read_error}')
                content = '[Fájl tartalma nem olvasható szöveges formátumban]'
        elif file_ext in {'jpg', 'jpeg', 'png', 'gif'}:
            content = '[Képfájl feltöltve - elemzéshez használjon képfelismerő modellt]'
        elif file_ext in {'pdf', 'doc', 'docx'}:
            content = '[Dokumentum feltöltve - teljes elemzéshez használjon dokumentum feldolgozó eszközt]'
        else:
            content = '[Bináris fájl feltöltve]'
        analysis_prompt = f"A felhasználó feltöltött egy fájlt:\nFájlnév: {filename}\nFájltípus: {file_ext}\nMéret: {file_size_display}\n\nTartalom (első 500000 karakter):\n{content}\n\n{(quickda_analysis if quickda_analysis else '')}\n\nKérlek, elemezd ezt a fájlt és adj rövid összefoglalót a tartalmáról."
        analysis = cerebras_client.chat.completions.create(model='gpt-oss-120b', messages=[{'role': 'user', 'content': analysis_prompt}], max_completion_tokens=65000, temperature=0.05, top_p=0.1)
        if not analysis.choices:
            ai_analysis = 'Hiba az elemzés során.'
        else:
            ai_analysis = analysis.choices[0].message.content if hasattr(analysis.choices[0].message, 'content') else 'Hiba az elemzés során.'
        try:
            pdf_filename = f'{timestamp}_{filename}_analysis.pdf'
            pdf_path = os.path.join(app.config['UPLOAD_FOLDER'], pdf_filename)
            doc = SimpleDocTemplate(pdf_path, pagesize=A4)
            styles = getSampleStyleSheet()
            story = []
            title_style = ParagraphStyle('CustomTitle', parent=styles['Heading1'], fontSize=24, textColor='darkblue', spaceAfter=30)
            story.append(Paragraph(f'File Analysis Report', title_style))
            story.append(Spacer(1, 12))
            story.append(Paragraph(f'<b>Filename:</b> {filename}', styles['Normal']))
            story.append(Paragraph(f'<b>Type:</b> {file_ext}', styles['Normal']))
            story.append(Paragraph(f'<b>Size:</b> {file_size_display}', styles['Normal']))
            story.append(Paragraph(f'<b>Upload Time:</b> {pendulum.now().to_datetime_string()}', styles['Normal']))
            story.append(Spacer(1, 20))
            story.append(Paragraph('<b>AI Analysis:</b>', styles['Heading2']))
            story.append(Spacer(1, 12))
            for para in ai_analysis.split('\n'):
                if para.strip():
                    story.append(Paragraph(para, styles['Normal']))
                    story.append(Spacer(1, 6))
            doc.build(story)
            logger.success(f'PDF analysis report generated: {pdf_filename}')
        except Exception as pdf_error:
            logger.error(f'Exception caught: {pdf_error}')
            logger.error(f'PDF generation failed: {str(pdf_error)}')
            pdf_filename = None
        content_preview = content[:10000] if len(content) > 10000 else content
        save_uploaded_file(unique_filename, filename, file_size, file_ext, ai_analysis, content)
        response_data = {'success': True, 'filename': unique_filename, 'original_filename': filename, 'size': file_size, 'size_display': file_size_display, 'type': file_ext, 'analysis': ai_analysis, 'content_preview': content_preview, 'upload_time': pendulum.now().to_iso8601_string()}
        if pdf_filename:
            response_data['pdf_report'] = pdf_filename
        if quickda_analysis:
            response_data['quickda_analysis'] = quickda_analysis
        return jsonify(response_data)
    except Exception as e:
        logger.error(f'Exception caught: {e}')
        logger.error(f'Upload error: {str(e)}')
        traceback.print_exc()
        return (jsonify({'error': str(e)}), 500)

