def execute_comprehensive_research(task_id):
    try:
        logger.info(f'Starting comprehensive research for task: {task_id}')
        with research_lock:
            if task_id not in research_tasks:
                task = get_research_task(task_id)
                if task:
                    research_tasks[task_id] = dict(task)
                else:
                    logger.error(f'Task {task_id} not found')
                    return
        goal = research_tasks[task_id]['goal']
        search_params = research_tasks[task_id].get('search_params', {})
        clean_goal = ftfy.fix_text(goal)
        with research_lock:
            research_tasks[task_id]['sub_agents'][0]['status'] = 'Aktív - Fő keresés...'
            research_tasks[task_id]['status'] = 'Források keresése...'
            task = research_tasks[task_id].copy()
        save_research_task(task_id, task)
        num_results = search_params.get('num_results', 100)
        search_type = search_params.get('search_type', 'auto')
        logger.info(f"Searching with Exa: query='{clean_goal}', num_results={num_results}")

        @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
        def exa_search_with_retry():
            return exa_client.search_and_contents(clean_goal, type=search_type, num_results=num_results, text={'max_characters': 10000}, highlights={'num_sentences': 5})
        search_result = exa_search_with_retry()
        sources = []
        for result in search_result.results:
            clean_title = ftfy.fix_text(result.title) if result.title else ''
            clean_url = result.url
            clean_author = ftfy.fix_text(result.author) if result.author else ''
            source_dict = {'id': getattr(result, 'id', ''), 'title': clean_title, 'url': clean_url, 'author': clean_author, 'published_date': result.published_date, 'score': getattr(result, 'score', None)}
            sources.append(source_dict)
        try:
            all_titles = glom(sources, ['title'])
            logger.info(f'Glom extracted {len(all_titles)} titles from sources')
        except GlomError as e:
            logger.warning(f'Glom extraction failed: {str(e)}')
            all_titles = [s['title'] for s in sources]
        total_sources_rounded = sigfig.round(len(sources), sigfigs=3)
        with research_lock:
            research_tasks[task_id]['sources'] = sources
            research_tasks[task_id]['metadata']['total_sources'] = total_sources_rounded
            research_tasks[task_id]['sub_agents'][0]['status'] = 'Befejezve'
            research_tasks[task_id]['sub_agents'][0]['progress'] = 100
            research_tasks[task_id]['progress'] = 20
            research_tasks[task_id]['sub_agents'][1]['status'] = 'Aktív - Tartalom gyűjtése...'
            research_tasks[task_id]['status'] = 'Tartalom gyűjtése...'
            task = research_tasks[task_id].copy()
        save_research_task(task_id, task)
        logger.info(f'Found {len(sources)} sources')
        deep_content = []
        source_ids = [s['id'] for s in sources if s.get('id')]
        if source_ids:
            logger.info(f'Fetching content for {len(source_ids)} sources')

            @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
            def exa_get_contents_with_retry(ids_batch):
                return exa_client.get_contents(ids=ids_batch, text={'max_characters': 10000}, highlights={'num_sentences': 5})
            batch_size = 20
            for i in range(0, len(source_ids), batch_size):
                batch = source_ids[i:i + batch_size]
                try:
                    content_result = exa_get_contents_with_retry(batch)
                    for content_item in content_result.results:
                        clean_text = ftfy.fix_text(content_item.text) if hasattr(content_item, 'text') and content_item.text else ''
                        clean_summary = ftfy.fix_text(content_item.summary) if hasattr(content_item, 'summary') and content_item.summary else ''
                        clean_title = ftfy.fix_text(content_item.title) if content_item.title else ''
                        if clean_text:
                            clean_text = clean(clean_text, fix_unicode=True, to_ascii=False, lower=False, no_line_breaks=False, no_urls=False, no_emails=False)
                        deep_content.append({'title': clean_title, 'url': content_item.url, 'text': clean_text, 'summary': clean_summary, 'author': ftfy.fix_text(content_item.author) if content_item.author else None, 'published_date': content_item.published_date})
                    time.sleep(0.5)
                except Exception as e:
                    logger.error(f'Exception caught: {e}')
                    logger.error(f'Error getting content batch: {e}')
                    continue
        with research_lock:
            research_tasks[task_id]['deep_content'] = deep_content
            research_tasks[task_id]['sub_agents'][1]['status'] = 'Befejezve'
            research_tasks[task_id]['sub_agents'][1]['progress'] = 100
            research_tasks[task_id]['progress'] = 35
            research_tasks[task_id]['sub_agents'][2]['status'] = 'Aktív - Hasonló források keresése...'
            research_tasks[task_id]['status'] = 'Hasonló források keresése...'
            task = research_tasks[task_id].copy()
        save_research_task(task_id, task)
        logger.info(f'Collected {len(deep_content)} detailed content items')
        similar_sources_list = []
        seen_urls = set()
        for source in sources[:10]:
            try:

                @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
                def exa_find_similar_with_retry(url):
                    return exa_client.find_similar(url=url, num_results=5, exclude_source_domain=True)
                similar_result = exa_find_similar_with_retry(source['url'])
                for sim_r in similar_result.results:
                    if sim_r.url in seen_urls:
                        continue
                    sim_title_clean = ftfy.fix_text(sim_r.title) if sim_r.title else ''
                    is_duplicate = False
                    for existing in similar_sources_list:
                        similarity = jellyfish.jaro_winkler_similarity(sim_title_clean.lower(), existing['title'].lower())
                        if similarity > 0.9:
                            is_duplicate = True
                            logger.debug(f'Duplicate detected with Jellyfish: {similarity:.2f} similarity')
                            break
                    if not is_duplicate:
                        seen_urls.add(sim_r.url)
                        similar_sources_list.append({'original_source': source['title'], 'title': sim_title_clean, 'url': sim_r.url, 'author': ftfy.fix_text(sim_r.author) if sim_r.author else None, 'published_date': sim_r.published_date, 'score': getattr(sim_r, 'score', None), 'similarity_to_original': None})
                time.sleep(0.5)
            except Exception as e:
                logger.error(f'Exception caught: {e}')
                logger.error(f"Error finding similar for {source['url']}: {e}")
                continue
        final_similar_sources = []
        for source in similar_sources_list:
            is_fuzzy_duplicate = False
            for existing in final_similar_sources:
                ratio = fuzz.token_sort_ratio(source['title'].lower(), existing['title'].lower())
                if ratio > 85:
                    is_fuzzy_duplicate = True
                    logger.debug(f'Fuzzy duplicate detected: {ratio}% match')
                    break
            if not is_fuzzy_duplicate:
                final_similar_sources.append(source)
        similar_sources_list = final_similar_sources
        with research_lock:
            research_tasks[task_id]['similar_sources'] = similar_sources_list
            research_tasks[task_id]['sub_agents'][2]['status'] = 'Befejezve'
            research_tasks[task_id]['sub_agents'][2]['progress'] = 100
            research_tasks[task_id]['progress'] = 50
            research_tasks[task_id]['sub_agents'][3]['status'] = 'Aktív - Mély elemzés...'
            research_tasks[task_id]['status'] = 'Mély AI elemzés...'
            task = research_tasks[task_id].copy()
        save_research_task(task_id, task)
        logger.info(f'Found {len(similar_sources_list)} similar sources (deduplicated)')
        analysis_sections = []
        take_first_100 = curry(take)(100)
        first_100_content = list(take_first_100(deep_content))
        section_1_content = '\n\n'.join([f"### Forrás {i + 1}: {item['title']}\n**URL:** {item['url']}\n**Szerző:** {item.get('author', 'N/A')}\n**Összefoglaló:**\n{item.get('summary', '')[:100000]}" for i, item in enumerate(first_100_content)])
        analysis_prompt_1 = f'Kutatási cél: {clean_goal}\n\nAz alábbi források első átfogó elemzése:\n\n{section_1_content}\n\n⚠️ KRITIKUS: TILOS bármit kitalálni! CSAK a fenti forrásokban szereplő információkat elemezd.\n\nKészíts részletes elemzést az alábbi szempontok szerint:\n1. Főbb témák és trendek azonosítása (CSAK a forrásokban említettekből)\n2. Kulcsfontosságú megállapítások összegyűjtése (CSAK idézetek a forrásokból)\n3. Ellentmondások vagy különböző nézőpontok kiemelése (ha VAN a forrásokban)\n4. Adatok és statisztikák összefoglalása (CSAK a forrásokban szereplők)\n5. Források megbízhatóságának értékelése\n\nHa bármely pontnál nincs információ a forrásokban, írd: "Nincs adat a forrásokban".'
        analysis_1 = cerebras_client.chat.completions.create(model='gpt-oss-120b', messages=[{'role': 'system', 'content': 'Te egy forrás-elemző vagy. TILOS kitalálnod információt. CSAK a megadott forrásokban szereplő adatokat elemezheted. Ha nincs adat, mondd meg őszintén.'}, {'role': 'user', 'content': analysis_prompt_1}], max_completion_tokens=65000, temperature=0.01, top_p=0.01)
        analysis_1_content = analysis_1.choices[0].message.content if analysis_1.choices and hasattr(analysis_1.choices[0].message, 'content') else 'Hiba az elemzés során.'
        analysis_1_content = ftfy.fix_text(analysis_1_content)
        analysis_sections.append({'title': '1. ÁTFOGÓ ELEMZÉS - ELSŐ FORRÁSCSOPORT', 'content': analysis_1_content})
        with research_lock:
