        section_2_content = '\n\n'.join([f"### Forrás {i + 16}: {item['title']}\n**URL:** {item['url']}\n**Szöveg részlet:**\n{item.get('text', '')[:100000]}" for i, item in enumerate(deep_content[15:30])])
