@app.route('/api/research/<task_id>', methods=['GET'])
def get_research(task_id):
    with research_lock:
        if task_id in research_tasks:
            return jsonify(research_tasks[task_id])
    task = get_research_task(task_id)
    if task:
        with research_lock:
            research_tasks[task_id] = dict(task)
        return jsonify(dict(task))
    return (jsonify({'error': 'Task not found'}), 404)

@app.route('/api/exa/find_similar', methods=['POST'])
def exa_find_similar():
    try:
        data = request.json
        url = data.get('url')
        if not url:
            return (jsonify({'error': 'URL is required'}), 400)
        num_results = data.get('num_results', 100)
        params = {'url': url, 'num_results': num_results}
        if data.get('category'):
            params['category'] = data['category']
        if data.get('exclude_source_domain') is not None:
            params['exclude_source_domain'] = data['exclude_source_domain']
        if data.get('start_published_date'):
            params['start_published_date'] = data['start_published_date']
        if data.get('end_published_date'):
            params['end_published_date'] = data['end_published_date']

        @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
        def find_similar_with_retry():
            return exa_client.find_similar(**params)
        result = find_similar_with_retry()
        return jsonify({'results': [{'title': ftfy.fix_text(r.title) if r.title else '', 'url': r.url, 'author': ftfy.fix_text(r.author) if r.author else None, 'published_date': r.published_date, 'score': getattr(r, 'score', None)} for r in result.results]})
    except Exception as e:
        logger.error(f'Exception caught: {e}')
        logger.error(f'Find similar error: {str(e)}')
        return (jsonify({'error': str(e)}), 500)

@app.route('/api/exa/get_contents', methods=['POST'])
