            return exa_client.get_contents(**params)
        result = get_contents_with_retry()
        return jsonify({'results': [{'title': ftfy.fix_text(r.title) if r.title else '', 'url': r.url, 'text': ftfy.fix_text(getattr(r, 'text', '')) if getattr(r, 'text', '') else '', 'summary': ftfy.fix_text(getattr(r, 'summary', '')) if getattr(r, 'summary', '') else ''} for r in result.results]})
    except Exception as e:
        logger.error(f'Exception caught: {e}')
        logger.error(f'Get contents error: {str(e)}')
        return (jsonify({'error': str(e)}), 500)

@app.route('/api/exa/search_multi', methods=['POST'])
def exa_search_multi():
    try:
        data = request.json
        queries = data.get('queries', [])
        if not queries:
            return (jsonify({'error': 'Queries are required'}), 400)
        results = []
        for query_data in queries:
            if not isinstance(query_data, dict):
                continue
            clean_query = ftfy.fix_text(query_data.get('query', ''))
            search_params = {'query': clean_query, 'num_results': query_data.get('num_results', 100), 'type': query_data.get('search_type', 'auto')}
            if query_data.get('category'):
                search_params['category'] = query_data['category']
            if not search_params['query']:
                continue

            @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=2, max=10))
            def search_with_retry():
                return exa_client.search(**search_params)
            search_result = search_with_retry()
            results.append({'query': clean_query, 'results': [{'title': ftfy.fix_text(r.title) if r.title else '', 'url': r.url, 'author': ftfy.fix_text(r.author) if r.author else None, 'published_date': r.published_date, 'score': getattr(r, 'score', None)} for r in search_result.results]})
        return jsonify({'results': results})
    except Exception as e:
        logger.error(f'Exception caught: {e}')
        logger.error(f'Search multi error: {str(e)}')
        return (jsonify({'error': str(e)}), 500)
